SELECT  *
WHERE
  {   { <http://ja.dbpedia.org/resource/Category:日本の市町村_(廃止)>
                  ?po  ?x
      }
    UNION
      { ?x  ?pi  <http://ja.dbpedia.org/resource/Category:日本の市町村_(廃止)> }
  }
ORDER BY ?pi ?po ?x

SELECT  *
WHERE
  {   { <http://ja.dbpedia.org/resource/Category:1280年代>
                  ?po  ?x
      }
    UNION
      { ?x  ?pi  <http://ja.dbpedia.org/resource/Category:1280年代> }
  }
ORDER BY ?pi ?po ?x

SELECT  (count(*) AS ?__c)
WHERE
  { { SELECT DISTINCT  ?s
      WHERE
        { ?s  ?_p_  ?_o_ }
    }
  }

SELECT  (count(*) AS ?__c)
WHERE
  { { SELECT  *
      WHERE
        { { SELECT DISTINCT  ?s
            WHERE
              { ?s  ?_p_  ?_o_ }
          }
        }
      LIMIT   10000
    }
  }

